package pro.megadedh.fooddelivery.features.main.ui.screens.dishesimport android.app.Dialogimport android.os.Bundleimport android.widget.Buttonimport android.widget.ImageViewimport android.widget.TextViewimport androidx.fragment.app.DialogFragmentimport androidx.fragment.app.FragmentManagerimport coil.loadimport com.google.android.material.dialog.MaterialAlertDialogBuilderimport com.google.android.material.snackbar.Snackbarimport pro.megadedh.core.ui.utils.argsimport pro.megadedh.fooddelivery.features.main.api.domain.model.result.Dishimport pro.megadedh.fooddelivery.features.main.ui.Rclass DishDialog : DialogFragment() {    private var dish by args<Dish>()    override fun onCreateDialog(savedInstanceState: Bundle?): Dialog {        val dialog = MaterialAlertDialogBuilder(requireContext())        val view = layoutInflater.inflate(R.layout.dialog_dish, null)        view.findViewById<ImageView>(R.id.btnClose)?.setOnClickListener {            dismiss()        }        view.findViewById<TextView>(R.id.tvPrice).text = getString(            R.string.dish_dialog_price_template,            dish.price,        )        view.findViewById<TextView>(R.id.tvWeight).text = getString(            R.string.dish_dialog_weight_template,            dish.weight,        )        view.findViewById<TextView>(R.id.tvDishName).text = dish.name        view.findViewById<TextView>(R.id.tvDishDescription).text = dish.description        view.findViewById<ImageView>(R.id.ivDialogDish).load(dish.imageUrl)        view.findViewById<Button>(R.id.btnAddDish).setOnClickListener {            Snackbar.make(view, "Корзины пока нет :(", Snackbar.LENGTH_LONG).show()        }        return dialog.setView(view)            .create()    }    companion object {        fun show(            fragmentManager: FragmentManager,            dish: Dish,        ) = DishDialog().apply {            this.dish = dish            this.show(fragmentManager, "DishDialog")        }    }}